using System;
using System.IO;
using WoWProbe;
class FishingTests
{
    static int passed,failed;
    static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e.Message);}}
    static void Assert(bool value,string why){if(!value)throw new Exception(why);}
    static void Reject(Action a){try{a();}catch(ArgumentException){return;}catch(FormatException){return;}catch(InvalidOperationException){return;}throw new Exception("expected rejection");}
    static int Main()
    {
        Test("defaults keep vendor and all live confirmations disabled",delegate{var s=new FishingSettings();Assert(s.CastKey==49&&s.InteractKey==70&&s.CastTimeoutMs==30000&&s.PostCatchDelayMs==1000&&!s.EnableVendor&&!s.BindingsConfirmed&&!s.AutoLootConfirmed&&!s.AudioConfirmed&&!s.AutoSellConfirmed,"unsafe defaults");FishingFixtures.Plan().Validate();});
        Test("first fresh frame casts once without native input",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);var c=e.Step(o,0);Assert(c.Action==FishingAction.Key&&c.Purpose==FishingPurpose.Cast&&c.Key==49&&e.Casts==1,"initial cast missing");});
        Test("one bite emits one reel and duplicate events never reel again",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBiteAtMs=1000;o.BiteConfidence=.95;var c=e.Step(o,1000);Assert(c.Purpose==FishingPurpose.Reel&&c.Key==70&&c.ExpectedBiteAtMs==1000,"bite not reeled");FishingFixtures.Frame(o,1100);Assert(e.Step(o,1100).Action!=FishingAction.Key&&e.Reels==1,"repeated reel");});
        Test("no bite recasts on the original thirty second deadline",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,29999);Assert(e.Step(o,29999).Action==FishingAction.None,"early recast");FishingFixtures.Frame(o,30000);var c=e.Step(o,30000);Assert(c.Purpose==FishingPurpose.Cast&&e.Casts==2&&e.Reels==0,"deadline lost");});
        Test("confirmed loot waits a full second before the next cast",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBiteAtMs=1000;o.BiteConfidence=.9;e.Step(o,1000);FishingFixtures.Frame(o,1200);o.Game.Farm.LootOpened++;o.Game.Farm.LootClosed++;e.Step(o,1200);Assert(e.ConfirmedCatches==1,"catch not confirmed");FishingFixtures.Frame(o,2199);Assert(e.Step(o,2199).Action==FishingAction.None,"early post-catch cast");FishingFixtures.Frame(o,2200);Assert(e.Step(o,2200).Purpose==FishingPurpose.Cast,"post-catch cast missing");});
        Test("failed reel preserves original deadline and never repeats F",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBiteAtMs=1000;o.BiteConfidence=.9;e.Step(o,1000);FishingFixtures.Frame(o,5000);Assert(e.Step(o,5000).Action==FishingAction.None,"failed reel reset timer");FishingFixtures.Frame(o,6000);o.LastBiteAtMs=6000;Assert(e.Step(o,6000).Action==FishingAction.None&&e.Reels==1,"failed reel repeated");FishingFixtures.Frame(o,30000);Assert(e.Step(o,30000).Purpose==FishingPurpose.Cast,"original deadline not respected");});
        Test("old future premature and low confidence bites cannot reel",delegate{foreach(int scenario in new[]{0,1,2,3}){var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p,1000);e.Step(o,1000);FishingFixtures.Frame(o,2000);o.LastBiteAtMs=scenario==0?900:scenario==1?2100:scenario==2?1500:1900;o.BiteConfidence=scenario==3?.4:.95;Assert(e.Step(o,2000).Action!=FishingAction.Key&&e.Reels==0,"invalid bite accepted");}});
        Test("confirmed bag full stops default stationary fishing",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBagTextAtMs=o.LastBagVoiceAtMs=1000;o.BagTextConfidence=o.BagVoiceConfidence=.95;Assert(e.Step(o,1000).Action==FishingAction.Stop,"stationary full did not stop");});
        Test("one bag channel cannot start vendor travel",delegate{var p=FishingFixtures.Plan(true);var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBagTextAtMs=1000;o.BagTextConfidence=.95;e.Step(o,1000);Assert(e.Status!="ReturnNpc","one-channel full accepted");});
        Test("known zero slots corroborates one fresh bag channel",delegate{var p=FishingFixtures.Plan(true);var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBagTextAtMs=1000;o.BagTextConfidence=.95;o.Game.FreeSlots=0;e.Step(o,1000);Assert(e.Status=="ReturnNpc","two-vote full rejected");});
        Test("old separated or future bag cues do not fuse",delegate{foreach(int scenario in new[]{0,1,2}){var p=FishingFixtures.Plan(true);var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,4000);o.LastBagTextAtMs=scenario==0?500:scenario==1?2001:4500;o.LastBagVoiceAtMs=4000;o.BagTextConfidence=o.BagVoiceConfidence=.95;e.Step(o,4000);Assert(e.Status!="ReturnNpc","invalid pair fused");}});
        Test("mutations of source plans and observations cannot alter engine ownership",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);p.Settings.CastKey=57;var o=FishingFixtures.Observation();Assert(e.Step(o,0).Key==49,"source plan leaked");var clone=o.Clone();clone.Game.Farm.X=0;Assert(o.Game.Farm.X==.5,"observation clone leaked");});
        Test("API failures unknown core and map changes block even duplicate frames",delegate{foreach(int scenario in new[]{0,1,2,3}){var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);o.CapturedAtMs=100;if(scenario==0)o.Game.Fresh=false;if(scenario==1)o.Game.Farm.KnownCore=false;if(scenario==2)o.Game.Farm.MapId++;if(scenario==3)o.Game.Farm.InCombat=true;Assert(e.Step(o,100).Action==FishingAction.Stop,"unsafe duplicate accepted");}});
        Test("audio failure is explicit unless timeout-only fallback was configured",delegate{var p=FishingFixtures.Plan();var o=FishingFixtures.Observation(p);o.AudioReady=false;Assert(new FishingEngine(p).Step(o,0).Action==FishingAction.Stop,"required audio missing");p.Settings.RequireAudio=false;var e=new FishingEngine(p);Assert(e.Step(o,0).Purpose==FishingPurpose.Cast,"timeout fallback blocked");FishingFixtures.Frame(o,1000);o.LastBiteAtMs=1000;o.BiteConfidence=.95;Assert(e.Step(o,1000).Action!=FishingAction.Key,"silent fallback used stale bite");});
        Test("monotonic clock reversal stops instead of extending a cast",delegate{var e=new FishingEngine(FishingFixtures.Plan());var o=FishingFixtures.Observation(null,1000);e.Step(o,1000);o.CapturedAtMs=900;Assert(e.Step(o,900).Action==FishingAction.Stop,"clock reversal accepted");});
        Test("plan files clear live confirmations and reject unknown fields",delegate{string path=Path.Combine(Path.GetTempPath(),"fishing-plan-"+Guid.NewGuid().ToString("N")+".json");try{var p=FishingFixtures.Plan(true);p.Settings.BindingsConfirmed=p.Settings.AudioConfirmed=p.Settings.AutoLootConfirmed=p.Settings.AutoSellConfirmed=p.Calibration.Confirmed=true;FishingPlanStore.Save(path,p);var q=FishingPlanStore.Load(path);Assert(!q.Settings.BindingsConfirmed&&!q.Settings.AudioConfirmed&&!q.Settings.AutoLootConfirmed&&!q.Settings.AutoSellConfirmed&&!q.Calibration.Confirmed&&q.Vendor.Name==p.Vendor.Name,"live flags imported");Assert(q.Fingerprint()==p.Fingerprint(),"acknowledgements changed semantic fingerprint");File.WriteAllText(path,File.ReadAllText(path).Insert(1,"\"Extra\":1,"));Reject(()=>FishingPlanStore.Load(path));}finally{if(File.Exists(path))File.Delete(path);}});
        Test("vendor plan must be reversible connected same-map and saved friendly NPC",delegate{foreach(int n in new[]{0,1,2,3}){var p=FishingFixtures.Plan(true);if(n==0)p.VendorRoute.AllowReverse=false;if(n==1)p.VendorRoute.Points[0].X=.2;if(n==2)p.VendorRoute.MapId++;if(n==3)p.Vendor.Kind="monster";Reject(()=>p.Validate());}});
        Test("a future bite cannot become valid merely by waiting for its timestamp",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,2000);o.LastBiteAtMs=2100;o.BiteConfidence=.95;e.Step(o,2000);FishingFixtures.Frame(o,2200);Assert(e.Step(o,2200).Action==FishingAction.None&&e.Reels==0,"future candidate matured into a reel");});
        Test("audio-unavailable cached voice cannot corroborate bag text",delegate{var p=FishingFixtures.Plan();p.Settings.RequireAudio=false;var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.AudioReady=false;o.LastBagTextAtMs=o.LastBagVoiceAtMs=1000;o.BagTextConfidence=o.BagVoiceConfidence=.95;Assert(e.Step(o,1000).Action!=FishingAction.Stop,"unavailable voice counted as a vote");});
        Test("a changed initial facing is restored before casting",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);o.Game.Farm.Facing=Math.PI;var c=e.Step(o,0);Assert(c.Purpose!=FishingPurpose.Cast&&e.Status=="RestoreFacing","cast before restoring saved facing");});
        Test("stopping vendor travel preserves its checkpoint phase and route index",delegate{var p=FishingFixtures.Plan(true);var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBagTextAtMs=o.LastBagVoiceAtMs=1000;o.BagTextConfidence=o.BagVoiceConfidence=.95;e.Step(o,1000);e.Stop("pause");Assert(e.CurrentCheckpoint.Phase=="ReturnNpc"&&e.CurrentCheckpoint.RouteIndex==0,"travel checkpoint lost");});
        Test("resume requires manual confirmation and rejects another plan",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var cp=e.CurrentCheckpoint;var o=FishingFixtures.Observation(p,1000);Reject(()=>e.Restore(cp,o,1000,false));var other=FishingFixtures.Plan();other.Name="other";Reject(()=>new FishingEngine(other).Restore(cp,o,1000,true));});
        Test("a resumed fishing checkpoint starts a new cast and ignores cached audio",delegate{var p=FishingFixtures.Plan();var old=new FishingEngine(p);var o=FishingFixtures.Observation(p);old.Step(o,0);old.Stop("pause");var e=new FishingEngine(p);FishingFixtures.Frame(o,5000);o.LastBiteAtMs=4900;o.BiteConfidence=.95;e.Restore(old.CurrentCheckpoint,o,5000,true);Assert(e.Step(o,5000).Purpose==FishingPurpose.Cast,"old cast was resumed");FishingFixtures.Frame(o,5800);Assert(e.Step(o,5800).Action==FishingAction.None&&e.Reels==0,"cached pre-resume bite accepted");});
        Test("travel checkpoint cannot join an unrecorded current position",delegate{var p=FishingFixtures.Plan(true);var cp=new FishingCheckpoint{PlanFingerprint=p.Fingerprint(),Phase="ReturnNpc",RouteIndex=1};var o=FishingFixtures.Observation(p,1000);o.Game.Farm.X=.2;Reject(()=>new FishingEngine(p).Restore(cp,o,1000,true));});
        Test("checkpoint store rejects contradictory phase index and plan binding",delegate{string path=Path.Combine(Path.GetTempPath(),"fishing-checkpoint-"+Guid.NewGuid().ToString("N")+".json");try{var p=FishingFixtures.Plan();var cp=new FishingEngine(p).CurrentCheckpoint;FishingCheckpointStore.Save(path,cp);Assert(FishingCheckpointStore.Load(path,p).Phase=="Ready","checkpoint roundtrip");cp.RouteIndex=1;Reject(()=>FishingCheckpointStore.Save(path,cp));}finally{if(File.Exists(path))File.Delete(path);}});
        Test("closed merchant and restored slots do not prove a merchant ever opened",delegate{var x=new FishingVendorCase();x.Observation.Game.FreeSlots=8;x.Observation.Game.InventoryRevision++;x.Tick();Assert(x.Engine.Status=="VendorWait"&&x.Engine.VendorVisits==0,"window closure fabricated selling proof");});
        Test("opened merchant must match the saved NPC token and name",delegate{var x=new FishingVendorCase();x.Observation.Game.MerchantOpen=true;x.Observation.Game.MerchantTargetToken=999;x.Observation.Game.MerchantNameHash=x.Plan.Vendor.NameHash;Assert(x.Tick().Action==FishingAction.Stop,"wrong merchant accepted");});
        Test("free-slot growth without an inventory revision does not finish selling",delegate{var x=new FishingVendorCase();x.Open();x.Observation.Game.FreeSlots=8;x.Tick();Assert(x.Engine.Status=="VendorWait","unproven inventory accepted");});
        Test("already-closed merchant is not sent an Escape key that could open a menu",delegate{var x=new FishingVendorCase();x.Open();x.Observation.Game.MerchantOpen=false;x.Observation.Game.FreeSlots=8;x.Observation.Game.InventoryRevision++;var c=x.Tick();Assert(x.Engine.Status=="ReturnSpot"&&c.Action==FishingAction.None,"Escape sent after merchant closed");});
        Test("merchant wait deadline still stops on a duplicate sequence",delegate{var x=new FishingVendorCase();x.Observation.CapturedAtMs=x.Now+15000;var c=x.Engine.Step(x.Observation,x.Now+15000);Assert(c.Action==FishingAction.Stop,"duplicate frame hid merchant timeout");});
        Test("restoring travel resumes only the next recorded segment without old reel input",delegate{var p=FishingFixtures.Plan(true);var cp=new FishingCheckpoint{PlanFingerprint=p.Fingerprint(),Phase="ReturnNpc",RouteIndex=1};var o=FishingFixtures.Observation(p,1000);o.LastBiteAtMs=900;o.BiteConfidence=.95;var e=new FishingEngine(p);e.Restore(cp,o,1000,true);var c=e.Step(o,1000);Assert(c.Purpose==FishingPurpose.Travel&&c.Key==p.Movement.Forward&&e.Reels==0&&e.Casts==0,"travel resume emitted old fishing input");});
        Test("store refuses duplicate keys numeric strings and failed saves preserve old file",delegate{string path=Path.Combine(Path.GetTempPath(),"fishing-strict-"+Guid.NewGuid().ToString("N")+".json");try{var p=FishingFixtures.Plan();FishingPlanStore.Save(path,p);string original=File.ReadAllText(path);File.WriteAllText(path,original.Insert(1,"\"Name\":\"duplicate\","));Reject(()=>FishingPlanStore.Load(path));File.WriteAllText(path,original.Replace("\"CastKey\":49","\"CastKey\":\"49\""));Reject(()=>FishingPlanStore.Load(path));File.WriteAllText(path,original);p.Settings.TapMs=500;Reject(()=>FishingPlanStore.Save(path,p));Assert(File.ReadAllText(path)==original,"failed save corrupted old plan");}finally{if(File.Exists(path))File.Delete(path);}});
        Test("timeout waits for the old channel to end within three hundred milliseconds",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);o.Game.Farm.Channeling=true;FishingFixtures.Frame(o,30000);Assert(e.Step(o,30000).Action==FishingAction.None&&e.Casts==1&&e.Reels==0,"recast while old channel was active");FishingFixtures.Frame(o,30200);o.Game.Farm.Channeling=false;Assert(e.Step(o,30200).Purpose==FishingPurpose.Cast&&e.Casts==2&&e.Reels==0,"did not recast after channel ended inside grace");});
        Test("an old channel beyond the bounded timeout grace stops without extra input",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);o.Game.Farm.Channeling=true;FishingFixtures.Frame(o,30301);var c=e.Step(o,30301);Assert(c.Action==FishingAction.Stop&&e.Casts==1&&e.Reels==0,"unbounded old channel was recast");});
        Test("duplicate frames cannot conceal an expired cast-channel grace",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);o.Game.Farm.Casting=true;o.CapturedAtMs=30301;Assert(e.Step(o,30301).Action==FishingAction.Stop&&e.Casts==1,"duplicate bypassed channel grace deadline");});
        Test("late reel without loot also waits for channel completion before recast",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,29900);o.LastBiteAtMs=29900;o.BiteConfidence=.95;Assert(e.Step(o,29900).Purpose==FishingPurpose.Reel,"late bite setup failed");o.Game.Farm.Channeling=true;FishingFixtures.Frame(o,30000);Assert(e.Step(o,30000).Action==FishingAction.None&&e.Casts==1,"loot wait recast an active channel");FishingFixtures.Frame(o,30300);o.Game.Farm.Channeling=false;Assert(e.Step(o,30300).Purpose==FishingPurpose.Cast&&e.Reels==1,"grace boundary changed one-reel contract");});
        Test("post-catch delay cannot cast over another active channel",delegate{var p=FishingFixtures.Plan();var e=new FishingEngine(p);var o=FishingFixtures.Observation(p);e.Step(o,0);FishingFixtures.Frame(o,1000);o.LastBiteAtMs=1000;o.BiteConfidence=.95;e.Step(o,1000);FishingFixtures.Frame(o,1200);o.Game.Farm.LootOpened++;o.Game.Farm.LootClosed++;e.Step(o,1200);FishingFixtures.Frame(o,2200);o.Game.Farm.Channeling=true;Assert(e.Step(o,2200).Action==FishingAction.Stop&&e.Casts==1,"post-catch cast ignored another channel");});
        Test("resuming an already-open saved merchant waits without another F",delegate{var x=new FishingVendorCase();x.Open();x.Engine.Stop("pause");var e=new FishingEngine(x.Plan);e.Restore(x.Engine.CurrentCheckpoint,x.Observation,x.Now,true);var c=e.Step(x.Observation,x.Now);Assert(e.Status=="VendorWait"&&c.Action==FishingAction.None,"open merchant was rescanned or interacted again");});
        Test("selling completed and closed while paused resumes the return route",delegate{var x=new FishingVendorCase();x.Open();x.Engine.Stop("pause");var cp=x.Engine.CurrentCheckpoint;x.Observation.Game.MerchantOpen=false;x.Observation.Game.FreeSlots=8;x.Observation.Game.InventoryRevision++;var e=new FishingEngine(x.Plan);e.Restore(cp,x.Observation,x.Now,true);var c=e.Step(x.Observation,x.Now);Assert(e.Status=="ReturnSpot"&&c.Action==FishingAction.None,"completed sale baseline was discarded or F/Escape repeated");});
        Test("selling completed but still-open while paused closes once without repeating F",delegate{var x=new FishingVendorCase();x.Open();x.Engine.Stop("pause");var cp=x.Engine.CurrentCheckpoint;x.Observation.Game.FreeSlots=8;x.Observation.Game.InventoryRevision++;var e=new FishingEngine(x.Plan);e.Restore(cp,x.Observation,x.Now,true);var c=e.Step(x.Observation,x.Now);Assert(e.Status=="ReturnSpot"&&c.Purpose==FishingPurpose.CloseMerchant&&c.Key==0x1B&&c.ExpectedTargetToken==123,"completed open sale did not close the verified merchant once");});
        Test("merchant resume rejects current unknown or mismatched merchant identity",delegate{foreach(bool unknown in new[]{false,true}){var x=new FishingVendorCase();x.Open();x.Engine.Stop("pause");if(unknown)x.Observation.Game.MerchantKnown=false;else x.Observation.Game.MerchantTargetToken=999;Reject(()=>new FishingEngine(x.Plan).Restore(x.Engine.CurrentCheckpoint,x.Observation,x.Now,true));}});
        Test("closed merchant without observed-open proof cannot fabricate paused selling",delegate{var x=new FishingVendorCase();x.Engine.Stop("pause");x.Observation.Game.FreeSlots=8;x.Observation.Game.InventoryRevision++;Reject(()=>new FishingEngine(x.Plan).Restore(x.Engine.CurrentCheckpoint,x.Observation,x.Now,true));});
        Test("current matching open merchant may establish proof after pause before its first open observation",delegate{var x=new FishingVendorCase();x.Engine.Stop("pause");x.Observation.Game.MerchantOpen=true;x.Observation.Game.MerchantTargetToken=123;x.Observation.Game.MerchantNameHash=x.Plan.Vendor.NameHash;var e=new FishingEngine(x.Plan);e.Restore(x.Engine.CurrentCheckpoint,x.Observation,x.Now,true);Assert(e.Step(x.Observation,x.Now).Action==FishingAction.None&&e.Status=="VendorWait","fresh matching open merchant did not resume bounded waiting");});
        Test("selling checkpoint file preserves the original baseline and observed merchant proof",delegate{string path=Path.Combine(Path.GetTempPath(),"fishing-sale-checkpoint-"+Guid.NewGuid().ToString("N")+".json");try{var x=new FishingVendorCase();x.Open();x.Engine.Stop("pause");FishingCheckpointStore.Save(path,x.Engine.CurrentCheckpoint);var cp=FishingCheckpointStore.Load(path,x.Plan);Assert(cp.VendorSlotsBefore==0&&cp.VendorInventoryRevision==0&&cp.VendorTargetToken==123&&cp.VendorNameHash==x.Plan.Vendor.NameHash&&cp.MerchantObserved,"selling baseline changed during file roundtrip");x.Observation.Game.MerchantOpen=false;x.Observation.Game.FreeSlots=8;x.Observation.Game.InventoryRevision++;var e=new FishingEngine(x.Plan);e.Restore(cp,x.Observation,x.Now,true);Assert(e.Step(x.Observation,x.Now).Action==FishingAction.None&&e.Status=="ReturnSpot","file recovery lost paused-sale evidence");}finally{if(File.Exists(path))File.Delete(path);}});
        Test("restored selling still requires a changed inventory revision",delegate{var x=new FishingVendorCase();x.Open();x.Engine.Stop("pause");x.Observation.Game.FreeSlots=8;var e=new FishingEngine(x.Plan);e.Restore(x.Engine.CurrentCheckpoint,x.Observation,x.Now,true);Assert(e.Step(x.Observation,x.Now).Action==FishingAction.None&&e.Status=="VendorWait","unchanged inventory revision completed restored selling");});
        Test("checkpoint merchant evidence is forbidden in other phases and must bind the saved NPC",delegate{string path=Path.Combine(Path.GetTempPath(),"fishing-invalid-checkpoint-"+Guid.NewGuid().ToString("N")+".json");try{var p=FishingFixtures.Plan();var cp=new FishingEngine(p).CurrentCheckpoint;cp.MerchantObserved=true;Reject(()=>FishingCheckpointStore.Save(path,cp));var x=new FishingVendorCase();x.Open();cp=x.Engine.CurrentCheckpoint;cp.VendorSlotsBefore=-1;Reject(()=>FishingCheckpointStore.Save(path,cp));cp=x.Engine.CurrentCheckpoint;cp.VendorNameHash=1;FishingCheckpointStore.Save(path,cp);Reject(()=>FishingCheckpointStore.Load(path,x.Plan));}finally{if(File.Exists(path))File.Delete(path);}});
        Test("initial positioning joins only the recorded middle or endpoint then follows the reverse remainder",delegate{foreach(int point in new[]{1,2}){var p=FishingFixtures.Plan(true);p.VendorRoute.Points.Insert(1,new Waypoint{X=.5,Y=.495,Tolerance=.001});var o=FishingFixtures.Observation(p);o.Game.Farm.X=p.VendorRoute.Points[point].X;o.Game.Farm.Y=p.VendorRoute.Points[point].Y;var e=new FishingEngine(p);var c=e.Step(o,0);Assert(e.Status=="GoSpot"&&c.Action==FishingAction.None&&e.RouteIndex==(point==1?2:1)&&e.Casts==0&&e.VendorVisits==0,"recorded-node initial join was missing or used the wrong reverse segment");}});
        Test("initial positioning rejects unrecorded points even inside the route corridor",delegate{var p=FishingFixtures.Plan(true);p.VendorRoute.Points.Insert(1,new Waypoint{X=.5,Y=.495,Tolerance=.001});var o=FishingFixtures.Observation(p);o.Game.Farm.Y=.4975;Assert(new FishingEngine(p).Step(o,0).Action==FishingAction.Stop,"an arbitrary corridor point was treated as a recorded node");p.Settings.EnableVendor=false;o=FishingFixtures.Observation(p);o.Game.Farm.Y=.49;Assert(new FishingEngine(p).Step(o,0).Action==FishingAction.Stop,"stationary plan moved without an enabled recorded return route");});
        Test("initial recorded return restores facing and casts without counting a sale",delegate{var p=FishingFixtures.Plan(true);p.VendorRoute.Points.Insert(1,new Waypoint{X=.5,Y=.495,Tolerance=.001});var o=FishingFixtures.Observation(p);o.Game.Farm.Y=.49;o.Game.Farm.Facing=Math.PI;var e=new FishingEngine(p);e.Step(o,0);long now=0;for(int n=0;n<30&&e.Casts==0&&e.Status!="Stopped";n++){if(e.Status=="GoSpot"){var route=p.VendorRoute.Reversed();var point=route.Points[Math.Min(route.Points.Count-1,e.RouteIndex)];o.Game.Farm.X=point.X;o.Game.Farm.Y=point.Y;}if(e.Status=="RestoreFacing")o.Game.Farm.Facing=p.Facing;FishingFixtures.Frame(o,now+=100);e.Step(o,now);}Assert(e.Casts==1&&e.VendorVisits==0&&e.ConfirmedCatches==0&&Math.Abs(o.Game.Farm.Facing-p.Facing)<.001,"initial route return was stopped or counted as a vendor transaction");});
        Test("initial positioning closes only the currently verified saved merchant",delegate{var p=FishingFixtures.Plan(true);var o=FishingFixtures.Observation(p);o.Game.Farm.Y=.49;var f=o.Game.Farm;f.TargetExists=f.TargetIdentityKnown=f.NameHashKnown=f.AttackabilityKnown=f.TargetDeadKnown=true;f.TargetToken=123;f.TargetNameHash=p.Vendor.NameHash;o.Game.MerchantOpen=true;o.Game.MerchantTargetToken=123;o.Game.MerchantNameHash=p.Vendor.NameHash;var e=new FishingEngine(p);var c=e.Step(o,0);Assert(e.Status=="GoSpot"&&c.Purpose==FishingPurpose.CloseMerchant&&c.Key==0x1B&&c.ExpectedTargetToken==123&&c.ExpectedNameHash==p.Vendor.NameHash&&e.VendorVisits==0,"initial position did not safely close the same merchant");});
        Test("unknown or mismatched merchant window blocks initial recorded travel",delegate{foreach(bool unknown in new[]{false,true}){var p=FishingFixtures.Plan(true);var o=FishingFixtures.Observation(p);o.Game.Farm.Y=.49;if(unknown)o.Game.MerchantKnown=false;else{o.Game.MerchantOpen=true;o.Game.MerchantTargetToken=999;o.Game.MerchantNameHash=p.Vendor.NameHash;}Assert(new FishingEngine(p).Step(o,0).Action==FishingAction.Stop,"unsafe initial merchant window allowed movement");}});
        Test("initial-position checkpoint recovery retains route progress and never invents a vendor visit",delegate{string path=Path.Combine(Path.GetTempPath(),"fishing-go-spot-"+Guid.NewGuid().ToString("N")+".json");try{var p=FishingFixtures.Plan(true);p.VendorRoute.Points.Insert(1,new Waypoint{X=.5,Y=.495,Tolerance=.001});var o=FishingFixtures.Observation(p);o.Game.Farm.Y=.49;var old=new FishingEngine(p);old.Step(o,0);old.Stop("pause");Assert(old.CurrentCheckpoint.Phase=="GoSpot","initial route phase was lost");FishingCheckpointStore.Save(path,old.CurrentCheckpoint);var cp=FishingCheckpointStore.Load(path,p);FishingFixtures.Frame(o,100);var e=new FishingEngine(p);e.Restore(cp,o,100,true);for(int n=0;n<30&&e.Casts==0&&e.Status!="Stopped";n++){if(e.Status=="GoSpot"){var route=p.VendorRoute.Reversed();var point=route.Points[Math.Min(route.Points.Count-1,e.RouteIndex)];o.Game.Farm.X=point.X;o.Game.Farm.Y=point.Y;}if(e.Status=="RestoreFacing")o.Game.Farm.Facing=p.Facing;FishingFixtures.Frame(o,200+n*100);e.Step(o,200+n*100);}Assert(e.Casts==1&&e.VendorVisits==0,"initial-position recovery fabricated a vendor visit or failed to cast");}finally{if(File.Exists(path))File.Delete(path);}});
        Console.WriteLine("Fishing tests: "+passed+" passed, "+failed+" failed. Pure state and file checks only.");return failed==0?0:1;
    }
